from PIL import Image
import numpy as np
from scipy.ndimage import label,find_objects
im=np.array(Image.open('first_frame.png'))[:,:,:3];r,g,b=im.transpose(2,0,1).astype(float)
for name,m in [('white',(r>145)&(g>140)&(b>140)&(np.maximum.reduce([r,g,b])-np.minimum.reduce([r,g,b])<30)),('black',(r<42)&(g<42)&(b<42))]:
 lab,n=label(m);areas=np.bincount(lab.ravel()); inds=areas[1:].argsort()[-8:][::-1]+1;slices=find_objects(lab)
 print(name,[(int(areas[i]),slices[i-1]) for i in inds]);
 if name=='white':
  obj=lab==inds[0]
  for y in range(650,1950,25):
   xs=np.where(obj[y])[0]
   if len(xs): print(y,xs.min(),xs.max())
# tool cropped low res grayscale, dark foreground shown as x
crop=Image.fromarray(im).crop((1770,0,2190,830)).resize((70,100))
a=np.array(crop).mean(2)
print('TOOL')
for row in a:
 print(''.join(' '@(0) if False else ('@' if v<25 else '#' if v<60 else '+' if v<100 else '.' if v<150 else ' ') for v in row))
PY"
